      /* nested /* CREATE FUNCTION public.nope() */ comment */
      CREATE FUNCTION public.real() RETURNS void AS $body$ BEGIN RAISE NOTICE 'CREATE FUNCTION public.fake2()'; END $body$ LANGUAGE plpgsql;
